import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.Cd9rfTEn.js";const m=JSON.parse('{"title":"CoopApps — Lo que faltaba mostrar","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/lo-que-faltaba-mostrar-para-imagenes.md","filePath":"presentacion-stakeholders/lo-que-faltaba-mostrar-para-imagenes.md","lastUpdated":null}'),i={name:"presentacion-stakeholders/lo-que-faltaba-mostrar-para-imagenes.md"};function r(t,a,l,c,d,p){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-lo-que-faltaba-mostrar" tabindex="-1">CoopApps — Lo que faltaba mostrar <a class="header-anchor" href="#coopapps-—-lo-que-faltaba-mostrar" aria-label="Permalink to &quot;CoopApps — Lo que faltaba mostrar&quot;">​</a></h1><p>Seis ideas importantes de la especificación que todavía no tenían imagen en la presentación. Cada una se sostiene con un dato de la especificación; ninguna promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td><code>T10-BIA</code> §15.5.1 (informes regulatorios REP-BIA-015 a REP-BIA-024), <code>M17-INS</code> (vida institucional), <code>M15-CON</code> §5.5 (motor de asientos automáticos), <code>01-registro-decisiones.md</code> (DEC-064, DEC-096 a DEC-103 y DEC-107), <code>docs/revision-externa/NucleoTransversal-contraste.md</code> y <code>NucleoTransversal-rechazados.md</code></td></tr><tr><td>Cómo se eligieron</td><td>Se compararon los temas de la especificación con los de todos los documentos de esta carpeta. Estos seis tenían mucho peso en la especificación y ninguna imagen, o casi ninguna mención, en la presentación</td></tr><tr><td>Datos</td><td>Todos los nombres e importes de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Puede usarse en la misma conversación que <code>lo-esencial-para-imagenes.md</code>. Si ya pegaste el prompt de estilo de ese documento, saltá directo al pedido.</li><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-N01&quot;, &quot;Generá IMG-N02&quot;, etc.</li><li>Cada idea trae una <strong>frase para decir</strong> en voz alta mientras se muestra la imagen.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar seis diapositivas para una reunión con directivos y stakeholders de trayectoria, de una empresa de software para cooperativas de servicios públicos de Argentina. Cada diapositiva transmite una sola idea, con un título corto y contundente y un dato que la respalda.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y lo muestra. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;disruptivo&quot;, &quot;el mejor&quot;), nada de signos de exclamación, nada de lenguaje publicitario.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras, comparaciones ni promesas. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina.</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo.</span></span>
<span class="line"><span>5. Composición de alto impacto: mucho espacio en blanco, un título grande (64 a 80 px), un elemento dominante y como máximo cuatro elementos de apoyo. Texto mínimo de 20 px.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de robots, cerebros, cohetes, personas sonriendo ni efectos futuristas.</span></span>
<span class="line"><span>8. Datos de ejemplo siempre ficticios (&quot;Cooperativa A&quot;, &quot;Socio de ejemplo&quot;, &quot;ARS 0.000&quot;).</span></span>
<span class="line"><span>9. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-N01 a IMG-N06).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><hr><h2 id="_1-las-seis-ideas" tabindex="-1">1. Las seis ideas <a class="header-anchor" href="#_1-las-seis-ideas" aria-label="Permalink to &quot;1. Las seis ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td>IMG-N01</td><td>Los informes a los organismos salen del mismo dato.</td><td>Cumplir con los reguladores deja de ser un trabajo aparte</td></tr><tr><td>IMG-N02</td><td>La vida institucional, dentro del sistema.</td><td>Asociados, asambleas, actas y excedentes, con la misma seriedad que la factura</td></tr><tr><td>IMG-N03</td><td>Una cooperativa, varias entidades. Una persona, una sola ficha.</td><td>La cooperativa, la mutual y sus socios, tal como son en la realidad</td></tr><tr><td>IMG-N04</td><td>La contabilidad se escribe sola.</td><td>Cada operación genera su asiento; nadie lo carga ni lo retoca a mano</td></tr><tr><td>IMG-N05</td><td>La migración no arrastra los problemas de hoy.</td><td>El paso de datos se controla antes, durante y después</td></tr><tr><td>IMG-N06</td><td>Escuchamos a todos. Decide la cooperativa.</td><td>Los aportes externos se contrastan y entran solo por decisión</td></tr></tbody></table><hr><h2 id="_2-fichas-y-prompts" tabindex="-1">2. Fichas y prompts <a class="header-anchor" href="#_2-fichas-y-prompts" aria-label="Permalink to &quot;2. Fichas y prompts&quot;">​</a></h2><h3 id="img-n01-—-los-informes-a-los-organismos-salen-del-mismo-dato" tabindex="-1">IMG-N01 — Los informes a los organismos salen del mismo dato. <a class="header-anchor" href="#img-n01-—-los-informes-a-los-organismos-salen-del-mismo-dato" aria-label="Permalink to &quot;IMG-N01 — Los informes a los organismos salen del mismo dato.&quot;">​</a></h3><p><strong>Respaldo:</strong> la especificación cataloga un informe por organismo y por servicio (REP-BIA-015 a REP-BIA-024), además de los de INAES y ARCA. Cada informe se arma con los mismos datos de consumos, facturación, reclamos e interrupciones que usa la operación diaria:</p><ul><li><strong>ENACOM:</strong> Internet, telefonía y televisión (accesos, abonados, reclamos por motivo y plazo de respuesta);</li><li><strong>organismo provincial de energía y agua</strong> (por ejemplo ERSeP en Córdoba): ventas, consumos, pérdidas, tarifa social, riesgo de corte, calidad de servicio e interrupciones, y calidad del agua;</li><li><strong>Secretaría de Energía:</strong> energía comprada y vendida, usuarios-generadores y energía inyectada;</li><li><strong>ENARGAS / ENReGE:</strong> usuarios, volúmenes, facturación, morosidad y reclamos por fuga;</li><li><strong>municipio:</strong> rendición del alumbrado público y de la concesión de saneamiento;</li><li><strong>INAES:</strong> Libro de Registro de Asociados, altas y bajas, estados contables y asambleas.</li></ul><p><strong>Frase para decir:</strong> &quot;El informe al regulador ya no se arma en una planilla aparte. Sale de los mismos datos con los que la cooperativa factura y atiende.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-N01 con código.</span></span>
<span class="line"><span>Título grande: &quot;Los informes a los organismos salen del mismo dato.&quot;</span></span>
<span class="line"><span>Composición: en el centro, un bloque verde &quot;Datos de la Cooperativa A&quot; con cuatro rótulos pequeños dentro: &quot;Consumos · Facturación · Reclamos · Interrupciones&quot;. De él salen seis líneas finas hacia seis tarjetas grises dispuestas en semicírculo, cada una con el organismo en negrita y una línea de contenido:</span></span>
<span class="line"><span>&quot;ENACOM&quot; — &quot;Internet, telefonía y TV&quot;</span></span>
<span class="line"><span>&quot;Organismo provincial (ej. ERSeP)&quot; — &quot;Energía y agua: ventas, calidad, tarifa social&quot;</span></span>
<span class="line"><span>&quot;Secretaría de Energía&quot; — &quot;Energía comprada, vendida e inyectada&quot;</span></span>
<span class="line"><span>&quot;ENARGAS / ENReGE&quot; — &quot;Gas: usuarios, volúmenes, fugas&quot;</span></span>
<span class="line"><span>&quot;Municipio&quot; — &quot;Alumbrado público y saneamiento&quot;</span></span>
<span class="line"><span>&quot;INAES&quot; — &quot;Asociados, estados contables y asambleas&quot;</span></span>
<span class="line"><span>Pie: &quot;Un informe por organismo y por servicio, catalogado en la especificación&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="img-n02-—-la-vida-institucional-dentro-del-sistema" tabindex="-1">IMG-N02 — La vida institucional, dentro del sistema. <a class="header-anchor" href="#img-n02-—-la-vida-institucional-dentro-del-sistema" aria-label="Permalink to &quot;IMG-N02 — La vida institucional, dentro del sistema.&quot;">​</a></h3><p><strong>Respaldo (M17):</strong></p><ul><li><strong>Asociados:</strong> número de asociado correlativo, nunca reutilizado; ingreso aprobado por acta y egreso con causa.</li><li><strong>Libro de Registro de Asociados:</strong> cada edición es inmutable, con folios correlativos y una huella digital (hash) que prueba que no se alteró; las correcciones van en la edición siguiente. El capital integrado del libro coincide con el saldo contable a la misma fecha.</li><li><strong>Asambleas:</strong> convocatoria con su documentación; el sistema bloquea publicarla con menos días que el mínimo configurado. Padrón versionado (preliminar, observado, definitivo), acreditación con credencial QR y quórum calculado en vivo.</li><li><strong>Actas:</strong> numeradas por libro (consejo, asamblea, sindicatura), con firma digital; una vez firmada no se edita, se corrige con un acta posterior.</li><li><strong>Excedentes:</strong> distribución según el esquema aprobado (reserva legal, fondos y retorno a asociados), separando las operaciones con no asociados.</li><li><strong>Roles:</strong> el consejo aprueba y firma; el síndico ve todo el módulo y firma sus actas.</li><li>Se construye en la ola O10; el registro mínimo de asociados, en O2.</li></ul><p><strong>Frase para decir:</strong> &quot;La asamblea, el padrón y el libro de asociados tienen el mismo rigor que una factura: nada se altera sin dejar rastro.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-N02 con código.</span></span>
<span class="line"><span>Título grande: &quot;La vida institucional, dentro del sistema.&quot;</span></span>
<span class="line"><span>Composición: una línea horizontal con cinco hitos del ciclo institucional, de izquierda a derecha, cada uno con ícono de línea, nombre y una línea de apoyo:</span></span>
<span class="line"><span>1. &quot;Asociado&quot; — &quot;Número único, ingreso por acta&quot;</span></span>
<span class="line"><span>2. &quot;Padrón&quot; — &quot;Versionado: preliminar, observado, definitivo&quot;</span></span>
<span class="line"><span>3. &quot;Asamblea&quot; — &quot;Acreditación con QR y quórum en vivo&quot;</span></span>
<span class="line"><span>4. &quot;Acta&quot; — &quot;Firma digital; firmada, no se edita&quot;</span></span>
<span class="line"><span>5. &quot;Excedentes&quot; — &quot;Reserva, fondos y retorno a asociados&quot;</span></span>
<span class="line"><span>Arriba de la línea, un libro abierto con un sello verde: &quot;Libro de Registro de Asociados · ediciones inmutables con huella digital&quot;.</span></span>
<span class="line"><span>Abajo, una franja gris claro con dos roles: &quot;Consejo: aprueba y firma&quot; · &quot;Síndico: ve todo y firma sus actas&quot;.</span></span>
<span class="line"><span>Pie: &quot;El capital del libro coincide con la contabilidad a la misma fecha&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="img-n03-—-una-cooperativa-varias-entidades-una-persona-una-sola-ficha" tabindex="-1">IMG-N03 — Una cooperativa, varias entidades. Una persona, una sola ficha. <a class="header-anchor" href="#img-n03-—-una-cooperativa-varias-entidades-una-persona-una-sola-ficha" aria-label="Permalink to &quot;IMG-N03 — Una cooperativa, varias entidades. Una persona, una sola ficha.&quot;">​</a></h3><p><strong>Respaldo:</strong></p><ul><li><strong>Varias entidades jurídicas por cooperativa</strong> (DEC-064 y DEC-096): una misma cooperativa puede administrar, por ejemplo, la cooperativa y una mutual. Cada entidad tiene su propia emisión de comprobantes, contabilidad, sueldos, libros sociales y numeración de asociados: el asociado N.º 1001 puede existir a la vez en la cooperativa y en la mutual. Los permisos de los usuarios también pueden limitarse por entidad.</li><li><strong>Persona única</strong> (DEC-097): un vecino que es socio, proveedor, chofer o instalador matriculado es <strong>una sola persona con varios roles</strong>, no cuatro fichas distintas. Toda alta pasa por el mismo control de duplicados.</li></ul><p><strong>Frase para decir:</strong> &quot;La cooperativa y la mutual llevan cada una sus libros, pero el vecino es uno solo, y el sistema lo sabe.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-N03 con código.</span></span>
<span class="line"><span>Título grande en dos líneas: &quot;Una cooperativa, varias entidades.&quot; / &quot;Una persona, una sola ficha.&quot;</span></span>
<span class="line"><span>Composición en dos mitades separadas por una línea vertical fina:</span></span>
<span class="line"><span>- Izquierda: un bloque grande &quot;Cooperativa A&quot; que contiene dos bloques iguales, &quot;Cooperativa&quot; y &quot;Mutual&quot;. Debajo de cada uno, la misma lista corta con tildes verdes: &quot;Comprobantes · Contabilidad · Sueldos · Libros sociales · Numeración de asociados&quot;. Entre ambos, una nota pequeña: &quot;Asociado N.º 1001 en las dos&quot;.</span></span>
<span class="line"><span>- Derecha: una tarjeta de persona en el centro, &quot;Socio de ejemplo&quot;, con cuatro etiquetas verdes alrededor unidas a ella: &quot;Socio&quot; · &quot;Proveedor&quot; · &quot;Chofer&quot; · &quot;Instalador matriculado&quot;.</span></span>
<span class="line"><span>Pie: &quot;Toda alta pasa por el mismo control de duplicados&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="img-n04-—-la-contabilidad-se-escribe-sola" tabindex="-1">IMG-N04 — La contabilidad se escribe sola. <a class="header-anchor" href="#img-n04-—-la-contabilidad-se-escribe-sola" aria-label="Permalink to &quot;IMG-N04 — La contabilidad se escribe sola.&quot;">​</a></h3><p><strong>Respaldo (M15):</strong></p><ul><li>Un <strong>motor de asientos automáticos</strong> genera el asiento de cada operación: facturación y cobranza desde la ola O5; luego mora, servicios medidos, compras, stock, tesorería, fiscal y sueldos.</li><li><strong>Un asiento automático no se edita:</strong> si algo está mal, se corrige la configuración, se revierte y se reprocesa, y queda un asiento nuevo vinculado al original.</li><li><strong>Las diferencias no se esconden:</strong> solo una diferencia mínima de redondeo, dentro de una tolerancia configurada, va a una cuenta de redondeo; cualquier diferencia mayor deja la operación en error para revisar.</li><li>Cada concepto se imputa a su centro de costo sin carga manual (por ejemplo, el abono de Internet va al centro de costo de Internet).</li></ul><p><strong>Frase para decir:</strong> &quot;El contador deja de pasar asientos y pasa a controlarlos. Y si algo no cierra, el sistema no lo tapa.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-N04 con código.</span></span>
<span class="line"><span>Título grande: &quot;La contabilidad se escribe sola.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, una columna de cinco operaciones con ícono de línea: &quot;Factura&quot; · &quot;Cobro&quot; · &quot;Compra&quot; · &quot;Movimiento de caja&quot; · &quot;Liquidación de sueldos&quot;. Todas convergen con flechas finas en un engranaje verde central, &quot;Motor de asientos&quot;. A la derecha, un libro mayor limpio con dos asientos ficticios (&quot;Debe ARS 0.000 · Haber ARS 0.000&quot;) y un candado pequeño: &quot;No editable&quot;.</span></span>
<span class="line"><span>Abajo, tres afirmaciones con tilde verde: &quot;Cada operación, su asiento&quot; · &quot;Se corrige revirtiendo, nunca retocando&quot; · &quot;Las diferencias grandes no se esconden: quedan en error&quot;.</span></span>
<span class="line"><span>Pie: &quot;Cada concepto va a su centro de costo sin carga manual&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="img-n05-—-la-migracion-no-arrastra-los-problemas-de-hoy" tabindex="-1">IMG-N05 — La migración no arrastra los problemas de hoy. <a class="header-anchor" href="#img-n05-—-la-migracion-no-arrastra-los-problemas-de-hoy" aria-label="Permalink to &quot;IMG-N05 — La migración no arrastra los problemas de hoy.&quot;">​</a></h3><p><strong>Respaldo:</strong></p><ul><li><strong>Antes de migrar:</strong> un escaneo de la base de origen busca números de tarjeta y columnas que parezcan contraseñas o credenciales; si encuentra alguno sin clasificar, <strong>la migración se bloquea</strong> (DEC-103). Las contraseñas y claves del sistema actual nunca se migran.</li><li><strong>Las sucursales las confirma la cooperativa:</strong> el sistema propone la lista y la cooperativa revisa nombres, domicilios y fusiones antes de migrar cajas y puntos de venta (DEC-098).</li><li><strong>Personas sin documento:</strong> no se descartan ni se inventan datos. Entran marcadas como &quot;documento pendiente&quot;, con una tarea de regularización, y no reciben comprobantes que exijan documento hasta regularizarse (DEC-099).</li><li><strong>Después:</strong> un verificador nocturno recorre las referencias entre los datos de cada cooperativa e informa cualquier referencia rota (DEC-100).</li><li>Para reemplazar la facturación se exigen 2 ciclos aprobados por servicio con 0 diferencias sin explicar (ya mostrado en IMG-22).</li></ul><p><strong>Frase para decir:</strong> &quot;No se trata de copiar la base vieja. Se trata de pasar los datos limpios y saber exactamente qué quedó pendiente.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-N05 con código.</span></span>
<span class="line"><span>Título grande: &quot;La migración no arrastra los problemas de hoy.&quot;</span></span>
<span class="line"><span>Composición: tres columnas, &quot;Antes&quot;, &quot;Durante&quot; y &quot;Después&quot;, unidas por una flecha horizontal que las atraviesa de izquierda a derecha:</span></span>
<span class="line"><span>- &quot;Antes&quot;: un escudo con la leyenda &quot;Escaneo de tarjetas y credenciales: si aparece una, se bloquea&quot; y debajo &quot;Las contraseñas no se migran&quot;.</span></span>
<span class="line"><span>- &quot;Durante&quot;: dos tarjetas: &quot;Sucursales: las confirma la cooperativa&quot; y, con borde ámbar, &quot;Personas sin documento: entran marcadas y con tarea de regularización&quot;.</span></span>
<span class="line"><span>- &quot;Después&quot;: una lupa con &quot;Verificador nocturno de referencias rotas&quot;.</span></span>
<span class="line"><span>Pie: &quot;Para reemplazar la facturación: 2 ciclos aprobados por servicio con 0 diferencias sin explicar&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-n06-—-escuchamos-a-todos-decide-la-cooperativa" tabindex="-1">IMG-N06 — Escuchamos a todos. Decide la cooperativa. <a class="header-anchor" href="#img-n06-—-escuchamos-a-todos-decide-la-cooperativa" aria-label="Permalink to &quot;IMG-N06 — Escuchamos a todos. Decide la cooperativa.&quot;">​</a></h3><p><strong>Respaldo:</strong> el 10-11-2026 se contrastó un documento externo de modelo de datos contra la especificación:</p><ul><li>se evaluaron <strong>112 temas</strong>, uno por cada subsección del documento;</li><li>se incorporaron <strong>11 aportes</strong>, aprobados de a uno, más la corrección de 11 inconsistencias internas que el contraste ayudó a encontrar;</li><li>las <strong>14 propuestas rechazadas</strong> se volvieron a revisar una por una; de esa revisión salieron 4 decisiones nuevas, incluida la adopción de una propuesta externa (el comprobante que ARCA rechaza vuelve a borrador y libera su número, DEC-107);</li><li>en total quedaron <strong>16 decisiones nuevas registradas</strong> (DEC-093 a DEC-108) y 4 preguntas para el contador;</li><li>regla de fondo: el documento externo <strong>no es fuente</strong>; nada entra sin una decisión registrada, y las decisiones prevalecen sobre cualquier otra fuente.</li></ul><p><strong>Frase para decir:</strong> &quot;Cualquiera puede aportar, y lo valoramos. Pero nada entra al diseño sin que alguien con autoridad lo decida y quede escrito.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-N06 con código.</span></span>
<span class="line"><span>Título grande: &quot;Escuchamos a todos. Decide la cooperativa.&quot;</span></span>
<span class="line"><span>Composición: un embudo horizontal de izquierda a derecha, en tres tramos con su cifra grande:</span></span>
<span class="line"><span>- Entrada, ancha, gris: &quot;112 temas evaluados&quot;.</span></span>
<span class="line"><span>- Centro: dos salidas: arriba en verde &quot;11 aportes incorporados&quot;; abajo en gris &quot;14 rechazos, revisados uno por uno&quot;.</span></span>
<span class="line"><span>- Salida, estrecha, verde oscuro: &quot;16 decisiones registradas&quot;.</span></span>
<span class="line"><span>A la derecha del embudo, un sello circular verde: &quot;Nada entra sin decisión&quot;.</span></span>
<span class="line"><span>Debajo, una franja gris claro: &quot;Una propuesta rechazada se terminó adoptando tras revisarla · 4 preguntas esperan al contador&quot;.</span></span>
<span class="line"><span>Pie: &quot;El documento externo no es fuente: las decisiones registradas prevalecen&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><h2 id="_3-notas-para-el-presentador" tabindex="-1">3. Notas para el presentador <a class="header-anchor" href="#_3-notas-para-el-presentador" aria-label="Permalink to &quot;3. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Dónde va cada una.</strong> N01 y N04 encajan después de IMG-E05 (&quot;Cada peso, explicado.&quot;). N02 y N03 van en el bloque de alcance, cerca del capital social (IMG-S16). N05 va junto a IMG-22 (&quot;Reemplazo de ProCoop sin saltos&quot;). N06 va antes de IMG-L03 (&quot;Leer. Decidir. Construir.&quot;), porque muestra en la práctica cómo se decide.</li><li><strong>Si solo hay lugar para dos:</strong> N01 (reguladores) y N02 (vida institucional). Son los temas que más preocupan a un consejo y que menos se ven en la presentación actual.</li><li><strong>N01: los formatos oficiales tienen dueño.</strong> La especificación cataloga qué informa cada organismo; los formatos exactos los definen los módulos fiscal, contable e institucional. Algunos regímenes provinciales dependen de cada cooperativa (por eso dice &quot;organismo provincial, por ejemplo ERSeP&quot;).</li><li><strong>N02: hay puntos legales a confirmar.</strong> Los plazos de convocatoria, el quórum, los porcentajes de distribución de excedentes y si algún libro social puede compartirse entre entidades llevan [VERIFICAR] con el asesor legal. La imagen no muestra plazos ni porcentajes por eso.</li><li><strong>N06 no nombra a los autores</strong> del documento externo.</li></ul>`,46)])])}const b=e(i,[["render",r]]);export{m as __pageData,b as default};
